import os
import platform

from .exception import ConfigPathDoesNotExist


class ConfigurationFilesCollector(object):
    """"Class to collect configuration data yaml files"""

    def __init__(self, location, testline):
        self.location, self.testline = location, testline

    @property
    def hran_configs_path(self):
        if platform.system().lower() == "windows":
            return r"C:\btsauto\hran_ta\config"
        else:
            return "/home/ute/btsauto/hran_ta/config"

    @property
    def common_config_path(self):
        return os.path.join(self.hran_configs_path, "common")

    @property
    def location_device_path(self):
        return os.path.join(self.hran_configs_path, self.location, "device")

    @property
    def testline_configs_path(self):
        return os.path.join(self.hran_configs_path, self.location, self.testline)

    @property
    def testline_device_path(self):
        return os.path.join(self.testline_configs_path, "device")

    def check_if_all_mandatory_config_paths_exist(self):
        for config_path in [self.common_config_path, self.location_device_path, self.testline_configs_path,
                            self.testline_device_path]:
            if not os.path.exists(config_path):
                raise ConfigPathDoesNotExist("Common configuration files path {config_path} "
                                             "does not exist".format(config_path=config_path))

    def get_all_yaml_configuration_files(self):
        self.check_if_all_mandatory_config_paths_exist()
        for config_path in [self.common_config_path, self.location_device_path, self.testline_configs_path,
                            self.testline_device_path]:
            for dirpath, dirnames, filenames in os.walk(config_path):
                for filename in filenames:
                    if filename.endswith('yaml'):
                        yield os.path.join(dirpath, filename)
